{
  "title": "Scholarship Application Dashboard",
  "subtitle": "Overview of applicant status, academic performance, and geographic distribution",
  "panels": [
    {
      "id": "p1",
      "kind": "kpi",
      "title": "Total Applicants",
      "sql": "SELECT COUNT(*) AS n FROM \"scholarship_applicants\"",
      "unit": ""
    },
    {
      "id": "p2",
      "kind": "kpi",
      "title": "Approved Count",
      "sql": "SELECT COUNT(*) AS n FROM \"scholarship_applicants\" WHERE \"Status\" = 'Approved'",
      "unit": ""
    },
    {
      "id": "p3",
      "kind": "kpi",
      "title": "Disbursed Count",
      "sql": "SELECT COUNT(*) AS n FROM \"scholarship_applicants\" WHERE \"Status\" = 'Disbursed'",
      "unit": ""
    },
    {
      "id": "p4",
      "kind": "kpi",
      "title": "Average Marks %",
      "sql": "SELECT AVG(\"Marks %\") AS avg_marks FROM \"scholarship_applicants\"",
      "unit": "%"
    },
    {
      "id": "p5",
      "kind": "bar",
      "title": "Applicants by Status",
      "sql": "SELECT \"Status\", COUNT(*) AS cnt FROM \"scholarship_applicants\" GROUP BY 1 ORDER BY 2 DESC",
      "x": "Status",
      "y": [
        "cnt"
      ]
    },
    {
      "id": "p6",
      "kind": "bar",
      "title": "Applicants by Taluka",
      "sql": "SELECT \"Taluka\", COUNT(*) AS cnt FROM \"scholarship_applicants\" GROUP BY 1 ORDER BY 2 DESC LIMIT 20",
      "x": "Taluka",
      "y": [
        "cnt"
      ]
    },
    {
      "id": "p7",
      "kind": "table",
      "title": "Top 10 Applicants by Marks",
      "sql": "SELECT \"Naam\", \"Marks %\", \"Status\", \"Taluka\" FROM \"scholarship_applicants\" ORDER BY \"Marks %\" DESC LIMIT 10"
    }
  ],
  "narrative": "There are currently {{p1}} total scholarship applicants in the system. Of these, {{p2}} have been approved and {{p3}} have had their funds disbursed. The average academic performance across all applicants is {{p4}}%. The distribution of applications across different statuses is shown in the bar chart, with the most common status being the one with the highest bar. Geographic distribution highlights which talukas have the highest volume of applicants. The table below lists the top 10 performers based on their marks percentage."
}

{
  "title": "Child Development: Baseline vs Endline",
  "subtitle": "Improvement metrics by location and coach",
  "panels": [
    {
      "id": "p1",
      "kind": "kpi",
      "title": "Total children tracked",
      "sql": "SELECT COUNT(*) AS n FROM (SELECT \"Child ID\" FROM baseline UNION SELECT \"Child ID\" FROM endline) AS all_children",
      "unit": ""
    },
    {
      "id": "p2",
      "kind": "bar",
      "title": "Avg height gain by location",
      "sql": "SELECT base.\"Location\", ROUND(AVG(end.\"Height cm\" - base.\"Height cm\"), 1) AS avg_height_gain FROM baseline AS base JOIN endline AS end ON base.\"Child ID\" = end.\"Child ID\" GROUP BY 1 ORDER BY 2 DESC",
      "x": "Location",
      "y": [
        "avg_height_gain"
      ]
    },
    {
      "id": "p3",
      "kind": "bar",
      "title": "Avg sit-ups gain by location",
      "sql": "SELECT base.\"Location\", ROUND(AVG(end.\"Sit ups\" - base.\"Sit ups\"), 1) AS avg_situps_gain FROM baseline AS base JOIN endline AS end ON base.\"Child ID\" = end.\"Child ID\" GROUP BY 1 ORDER BY 2 DESC",
      "x": "Location",
      "y": [
        "avg_situps_gain"
      ]
    },
    {
      "id": "p4",
      "kind": "bar",
      "title": "Avg height gain by coach",
      "sql": "SELECT base.\"Coach\", ROUND(AVG(end.\"Height cm\" - base.\"Height cm\"), 1) AS avg_height_gain FROM baseline AS base JOIN endline AS end ON base.\"Child ID\" = end.\"Child ID\" GROUP BY 1 ORDER BY 2 DESC",
      "x": "Coach",
      "y": [
        "avg_height_gain"
      ]
    },
    {
      "id": "p5",
      "kind": "bar",
      "title": "Avg sit-ups gain by coach",
      "sql": "SELECT base.\"Coach\", ROUND(AVG(end.\"Sit ups\" - base.\"Sit ups\"), 1) AS avg_situps_gain FROM baseline AS base JOIN endline AS end ON base.\"Child ID\" = end.\"Child ID\" GROUP BY 1 ORDER BY 2 DESC",
      "x": "Coach",
      "y": [
        "avg_situps_gain"
      ]
    },
    {
      "id": "p6",
      "kind": "table",
      "title": "Top 10 locations by overall improvement",
      "sql": "SELECT base.\"Location\", ROUND(AVG(end.\"Height cm\" - base.\"Height cm\"), 1) AS avg_height_gain, ROUND(AVG(end.\"Sit ups\" - base.\"Sit ups\"), 1) AS avg_situps_gain FROM baseline AS base JOIN endline AS end ON base.\"Child ID\" = end.\"Child ID\" GROUP BY 1 ORDER BY 2 DESC, 3 DESC LIMIT 10"
    }
  ],
  "narrative": "This dashboard compares baseline and endline measurements for children across different locations and coaches. The total number of unique children tracked is {{p1}}. On average, children in the top-performing locations gained {{p2.avg_height_gain}} cm in height and {{p3.avg_situps_gain}} sit-ups. When looking at coaches, the highest height gain was {{p4.avg_height_gain}} cm, while the best sit-ups improvement was {{p5.avg_situps_gain}}. The table highlights the top 10 locations based on these combined metrics."
}

{
  "title": "Donation Dashboard",
  "subtitle": "Monthly trends, top cities, payment modes, and repeat donors",
  "panels": [
    {
      "id": "p1",
      "kind": "kpi",
      "title": "Total Donations",
      "sql": "SELECT SUM(\"Amount\") AS total FROM \"donor_transactions\"",
      "unit": ""
    },
    {
      "id": "p2",
      "kind": "kpi",
      "title": "Unique Donors",
      "sql": "SELECT COUNT(DISTINCT \"Donor\") AS n FROM \"donor_transactions\"",
      "unit": ""
    },
    {
      "id": "p3",
      "kind": "line",
      "title": "Monthly Donation Trend",
      "sql": "SELECT \"Date\" AS month, SUM(\"Amount\") AS total FROM \"donor_transactions\" GROUP BY 1 ORDER BY 1",
      "x": "month",
      "y": [
        "total"
      ]
    },
    {
      "id": "p4",
      "kind": "bar",
      "title": "Top Cities by Donation",
      "sql": "SELECT \"City\", SUM(\"Amount\") AS total FROM \"donor_transactions\" GROUP BY 1 ORDER BY 2 DESC LIMIT 10",
      "x": "City",
      "y": [
        "total"
      ]
    },
    {
      "id": "p5",
      "kind": "bar",
      "title": "Donations by Payment Mode",
      "sql": "SELECT \"Mode\", SUM(\"Amount\") AS total FROM \"donor_transactions\" GROUP BY 1 ORDER BY 2 DESC",
      "x": "Mode",
      "y": [
        "total"
      ]
    },
    {
      "id": "p6",
      "kind": "table",
      "title": "Top 10 Repeat Donors",
      "sql": "SELECT \"Donor\", COUNT(*) AS donation_count, SUM(\"Amount\") AS total_amount FROM \"donor_transactions\" GROUP BY 1 HAVING COUNT(*) > 1 ORDER BY 2 DESC LIMIT 10"
    }
  ],
  "narrative": "The total donations stand at {{p1}}. There are {{p2}} unique donors in the system. The monthly trend shows the fluctuation in contributions over time. The top cities by donation volume are led by {{p4.City.0}} with {{p4.total.0}}. Payment modes show that {{p5.Mode.0}} is the most popular method, contributing {{p5.total.0}}. Among repeat donors, {{p6.Donor.0}} has made {{p6.donation_count.0}} donations totaling {{p6.total_amount.0}}."
}

